package com.mytraining;
import android.app.*; import android.os.*; import android.content.*; import android.webkit.*; import android.view.WindowManager;
public class MainActivity extends Activity { WebView web; String pendingText;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WebView w=new WebView(this);web=w;w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.setWebChromeClient(new WebChromeClient());w.addJavascriptInterface(new Bridge(),"Android");setContentView(w);w.loadUrl("file:///android_asset/index.html");}
 class Bridge {
 @JavascriptInterface public void donate(){runOnUiThread(()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.paypal.com/donate/?hosted_button_id=2HFNF4PJNC7DG"))));}
 @JavascriptInterface public void saveFile(String name,String mime,String data){runOnUiThread(()->{pendingText=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,10);});}
 @JavascriptInterface public void pickFile(){runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),11));}
 @JavascriptInterface public void shareFile(String name,String mime,String data){runOnUiThread(()->{try{java.io.File f=new java.io.File(getCacheDir(),"RUOSS-schede.json");try(java.io.FileOutputStream o=new java.io.FileOutputStream(f)){o.write(data.getBytes("UTF-8"));}android.net.Uri u=android.net.Uri.parse("content://com.mytraining.share/RUOSS-schede.json");Intent i=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri(name,u));startActivity(Intent.createChooser(i,"Condividi scheda RUOSS"));}catch(Exception e){ToastMessage("Condivisione non riuscita");}});}

 @JavascriptInterface public void scheduleRest(long end,String name){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);PendingIntent p=alarm(name);a.cancel(p);try{if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,p);}catch(SecurityException e){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,p);}}
 @JavascriptInterface public void cancelRest(){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(alarm(""));}
 }
 void ToastMessage(String s){android.widget.Toast.makeText(this,s,android.widget.Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;try{if(req==10){try(java.io.OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(pendingText.getBytes("UTF-8"));}ToastMessage("File salvato");}if(req==11){try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1000000)throw new Exception("File troppo grande");}web.evaluateJavascript("importPlan("+org.json.JSONObject.quote(out.toString("UTF-8"))+")",null);}}}catch(Exception e){ToastMessage("Operazione non riuscita: "+e.getMessage());}}
 PendingIntent alarm(String name){return PendingIntent.getBroadcast(this,1,new Intent(this,RestReceiver.class).putExtra("name",name),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
}